CREATE TABLE IF NOT EXISTS processing_meta(id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL, limits TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS processing_graphs(namespace TEXT NOT NULL, pipeline TEXT NOT NULL, version INTEGER NOT NULL, body TEXT NOT NULL, PRIMARY KEY(namespace,pipeline,version));
CREATE TABLE IF NOT EXISTS terminal_bindings(id TEXT NOT NULL, version INTEGER NOT NULL, identity TEXT NOT NULL, active INTEGER NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS processing_state(namespace TEXT NOT NULL,pipeline TEXT NOT NULL,node TEXT NOT NULL,key TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0, value TEXT NOT NULL, schema TEXT NOT NULL, generation INTEGER NOT NULL DEFAULT 0, owner TEXT, deadline INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(namespace,pipeline,node,key));
CREATE TABLE IF NOT EXISTS processing_deliveries(id INTEGER PRIMARY KEY AUTOINCREMENT, namespace TEXT NOT NULL,pipeline TEXT NOT NULL,graph_version INTEGER NOT NULL,node TEXT NOT NULL,key TEXT NOT NULL,origin TEXT NOT NULL,event TEXT NOT NULL,parent INTEGER REFERENCES processing_deliveries(id),status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0, generation INTEGER,incarnation INTEGER, outcome TEXT, failure TEXT, reserved_bytes INTEGER NOT NULL, FOREIGN KEY(namespace,pipeline,graph_version) REFERENCES processing_graphs(namespace,pipeline,version));
CREATE TABLE IF NOT EXISTS processing_ingress(namespace TEXT NOT NULL,client TEXT NOT NULL,conversation TEXT NOT NULL,operation TEXT NOT NULL,canonical TEXT NOT NULL,delivery INTEGER NOT NULL REFERENCES processing_deliveries(id),PRIMARY KEY(namespace,client,conversation,operation));
CREATE INDEX IF NOT EXISTS processing_pending ON processing_deliveries(status,id);
